// Общие помощники для тестов «4 последние цифры карты SafePay». План: specs/cards.md.
// Цифры временные и выдаются сервером → в тестах сверяем формат и совпадение между экранами, не значения.
import { expect, Page } from '@playwright/test';

/** «•••• •••• •••• NNNN» (допускается невидимая метка направления LRM/RLM в начале). */
export const MASK = /^[\u200e\u200f]?•••• •••• •••• (\d{4})$/;
export const MASK_DOTS_ONLY = /•••• •••• •••• ••••/;
export const HINT = 'הצמידו את מכשיר הטלפון למסוף כדי לשלם בכרטיס המוצג';
/** Общий кошелёк менеджера 04 (участник 05). Можно переопределить через QA_SHARED_WALLET_ID. */
export const SHARED_WALLET_ID = process.env.QA_SHARED_WALLET_ID || '3bf0fc53-2b78-46d2-9f53-f824c57ceb39';
export const SHARED_WALLET_NAME = 'QA-ארנק משותף 03.10';

/** Все «маски» на странице: массив из 4 цифр (по одному элементу на найденную маску). */
export async function readMasks(page: Page): Promise<string[]> {
  return page.evaluate(
    ({ src }) => {
      const re = new RegExp(src);
      const norm = (s: string | null) => (s || '').replace(/\s+/g, ' ').trim();
      const hit = (el: Element) => re.test(norm(el.textContent));
      const out: string[] = [];
      for (const el of Array.from(document.body.querySelectorAll('*'))) {
        if (!hit(el)) continue;
        if (Array.from(el.children).some(hit)) continue; // берём самый вложенный элемент
        const m = re.exec(norm(el.textContent));
        if (m) out.push(m[1]);
      }
      return out;
    },
    { src: MASK.source },
  );
}

/** Ждёт, пока на странице появится хотя бы одна маска, и возвращает все. */
export async function waitMasks(page: Page, min = 1): Promise<string[]> {
  await expect.poll(async () => (await readMasks(page)).length, { timeout: 30_000 }).toBeGreaterThanOrEqual(min);
  return readMasks(page);
}

/** 4 цифры карточки, содержащей подпись label (ближайший предок с маской). Падает, если масок в нём не одна. */
export async function digitsOfCard(page: Page, label: string): Promise<string> {
  const res = await page.evaluate(
    ({ src, label }) => {
      const re = new RegExp(src);
      const norm = (s: string | null) => (s || '').replace(/\s+/g, ' ').trim();
      const leaf = Array.from(document.body.querySelectorAll('*')).find(
        (e) => e.children.length === 0 && norm(e.textContent) === label,
      );
      if (!leaf) return { error: 'нет подписи «' + label + '»' };
      let el: Element | null = leaf;
      while (el && el !== document.body) {
        const found = Array.from(el.querySelectorAll('*')).filter(
          (c) => re.test(norm(c.textContent)) && !Array.from(c.children).some((d) => re.test(norm(d.textContent))),
        );
        if (found.length) {
          if (found.length > 1) return { error: 'в карточке «' + label + '» масок: ' + found.length };
          return { digits: re.exec(norm(found[0].textContent))![1] };
        }
        el = el.parentElement;
      }
      return { error: 'у «' + label + '» нет маски' };
    },
    { src: MASK.source, label },
  );
  if ('error' in res) throw new Error(res.error);
  return res.digits as string;
}

/** Главная → «צפייה בכרטיסים» → экран «כל הכרטיסים»; ждёт подсказку. */
export async function openAllCards(page: Page): Promise<void> {
  await page.goto('/wallet');
  await expect(page.getByText('היתרה שלך').first()).toBeVisible({ timeout: 30_000 });
  await page.getByText('צפייה בכרטיסים', { exact: true }).first().click();
  await expect(page.getByText(HINT)).toBeVisible({ timeout: 30_000 });
}

/** Страница не содержит полного номера карты (13–19 цифр подряд, с пробелами/дефисами или без). */
export async function expectNoFullCardNumber(page: Page): Promise<void> {
  const text = await page.locator('body').innerText();
  expect(text).not.toMatch(/\b(?:\d[ -]?){13,19}\b/);
}
